import React from "react";
import { FaBolt, FaUserGraduate, FaLeaf, FaTrophy, FaProjectDiagram, FaCalendarAlt, FaPalette } from "react-icons/fa";

const Projects = () => {
  return (
    <section className="projects">

      {/* HEADER */}
      <div className="header">
        <h1>Projects & Impact</h1>
        <p>Structured builds focused on UI, logic, and real-world problem solving</p>
      </div>

      {/* PROJECT FLOW LIST */}
      <div className="flow">

        {/* PROJECT 1 */}
        <div className="flow-item">
          <div className="icon"><FaBolt /></div>
          <div className="content">
            <h2>EnergyPulse</h2>
            <p>
              Developed the frontend of an AI-driven smart home solution,
              creating a responsive dashboard for real-time biometric and
              energy monitoring. Focused on clean UI and smooth interaction flow.
            </p>
            <span>Tech: React.js</span>
          </div>
        </div>

        {/* PROJECT 2 */}
        <div className="flow-item">
          <div className="icon"><FaUserGraduate /></div>
          <div className="content">
            <h2>Student Portal Management</h2>
            <p>
              Built a full-stack student management system using Java and Spring Boot.
              Implemented structured backend APIs and a simple interactive frontend
              for academic record handling.
            </p>
            <span>Tech: Spring Boot, HTML, CSS, JavaScript, MySQL</span>
          </div>
        </div>

        {/* PROJECT 3 */}
        <div className="flow-item">
          <div className="icon"><FaLeaf /></div>
          <div className="content">
            <h2>Farm2Fork</h2>
            <p>
              Designed a responsive platform connecting farmers and consumers.
              Focused on smooth navigation, product listing UI, and efficient
              browsing experience.
            </p>
            <span>Tech: HTML, CSS, JavaScript</span>
          </div>
        </div>

      </div>

      {/* ACHIEVEMENTS TIMELINE */}
      <div className="achievements">

        <h2>Achievements</h2>

        <div className="timeline">

          <div className="item">
            <FaTrophy />
            <p>Semifinalist – Smart India Hackathon (SIH)</p>
          </div>

          <div className="item">
            <FaProjectDiagram />
            <p>Best Project Award – Li-Fi Innovation (International Conference)</p>
          </div>

          <div className="item">
            <FaCalendarAlt />
            <p>Organized Code Crunch – DSA Coding Event</p>
          </div>

          <div className="item">
            <FaPalette />
            <p>Conducted Tech & Non-Tech College Events</p>
          </div>

        </div>

      </div>

      {/* STYLE */}
      <style>{`

        .projects {
          min-height: 100vh;
          padding: 40px 10%;
          background: radial-gradient(circle at top, #0b1220, #050816);
          color: white;
          font-family: "Poppins", sans-serif;
        }

        /* HEADER */
        .header {
          text-align: center;
          margin-bottom: 50px;
        }

        .header h1 {
          font-size: 40px;
          color: #e2e8f0;
        }

        .header p {
          color: #94a3b8;
          margin-top: 8px;
        }

        /* FLOW DESIGN */
        .flow {
          display: flex;
          flex-direction: column;
          gap: 25px;
        }

        .flow-item {
          display: flex;
          gap: 20px;
          padding: 22px;
          border-radius: 16px;
          background: rgba(255,255,255,0.03);
          border: 1px solid rgba(56,189,248,0.15);
          transition: 0.3s;
        }

        .flow-item:hover {
          transform: translateX(6px);
          border-color: #38BDF8;
          box-shadow: 0 0 20px rgba(56,189,248,0.15);
        }

        .icon {
          font-size: 26px;
          color: #38BDF8;
          margin-top: 4px;
        }

        .content h2 {
          margin: 0;
          color: #38BDF8;
          font-size: 20px;
        }

        .content p {
          margin-top: 6px;
          color: #cbd5e1;
          line-height: 1.6;
          max-width: 750px;
        }

        .content span {
          display: inline-block;
          margin-top: 8px;
          color: #94a3b8;
          font-size: 13px;
        }

        /* ACHIEVEMENTS */
        .achievements {
          margin-top: 60px;
        }

        .achievements h2 {
          color: #38BDF8;
          margin-bottom: 20px;
        }

        .timeline {
          display: flex;
          flex-direction: column;
          gap: 12px;
        }

        .item {
          display: flex;
          align-items: center;
          gap: 12px;
          padding: 14px;
          border-left: 3px solid #38BDF8;
          background: rgba(255,255,255,0.03);
          border-radius: 10px;
        }

        .item svg {
          color: #38BDF8;
        }

        .item p {
          margin: 0;
          color: #cbd5e1;
        }

        /* RESPONSIVE */
        @media (max-width: 900px) {
          .flow-item {
            flex-direction: column;
          }
        }

      `}</style>

    </section>
  );
};

export default Projects;
